-- [core] Recruiting companies (DataScience Jobs); units of one group linked by company_group
CREATE TABLE `dim_company` (
  `company_id` SMALLINT NOT NULL COMMENT 'Surrogate key',
  `company_name` VARCHAR(49) NOT NULL COMMENT 'Company name as listed (trimmed)',
  `company_group` VARCHAR(49) NOT NULL COMMENT 'Parent group (e.g. HSBC for Hsbc Technology)',
  `company_type` ENUM('IT services / consulting','Product / captive / other') NOT NULL COMMENT 'Curated classification',
  `is_placeholder_employer` TINYINT(1) NOT NULL COMMENT '1 = \'Confidential\', \'Xyz Company\' etc.',
  PRIMARY KEY (`company_id`),
  UNIQUE KEY `uq_company_name` (`company_name`),
  KEY `ix_company_group` (`company_group`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Recruiting companies (DataScience Jobs); units of one group linked by company_group';

-- [core] The 10 job titles in DataScience Jobs, split into base role and seniority
CREATE TABLE `dim_job_title` (
  `job_title_id` TINYINT NOT NULL COMMENT 'Surrogate key',
  `job_title` VARCHAR(40) NOT NULL COMMENT 'Job title as published',
  `base_role` VARCHAR(40) NOT NULL COMMENT 'Title without \'Senior\'',
  `seniority` ENUM('Junior/Mid','Senior') NOT NULL COMMENT 'Seniority',
  PRIMARY KEY (`job_title_id`),
  UNIQUE KEY `uq_job_title` (`job_title`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='The 10 job titles in DataScience Jobs, split into base role and seniority';

-- [core] Canonical cities / metro areas (100+ raw spellings and localities mapped)
CREATE TABLE `dim_city` (
  `city_id` SMALLINT NOT NULL COMMENT 'Surrogate key',
  `city_name` VARCHAR(30) NOT NULL COMMENT 'Canonical name',
  `city_category` ENUM('Tier 1 metro','Tier 2/3','Unspecified','International') NOT NULL COMMENT 'City tier',
  PRIMARY KEY (`city_id`),
  UNIQUE KEY `uq_city_name` (`city_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Canonical cities / metro areas (100+ raw spellings and localities mapped)';

-- [core] Role families derived from 10,097 free-text designations
CREATE TABLE `dim_role_family` (
  `role_family_id` TINYINT NOT NULL COMMENT 'Surrogate key',
  `role_family` VARCHAR(50) NOT NULL COMMENT 'Role family',
  `is_analytics` TINYINT(1) NOT NULL COMMENT '1 = one of the 9 analytics families',
  PRIMARY KEY (`role_family_id`),
  UNIQUE KEY `uq_role_family` (`role_family`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Role families derived from 10,097 free-text designations';

-- [core] Seniority levels from job titles
CREATE TABLE `dim_seniority` (
  `seniority_id` TINYINT NOT NULL COMMENT 'Surrogate key',
  `seniority` VARCHAR(20) NOT NULL COMMENT 'Level',
  `seniority_rank` TINYINT NOT NULL COMMENT '1 = Entry ... 5 = Leadership',
  PRIMARY KEY (`seniority_id`),
  UNIQUE KEY `uq_seniority` (`seniority`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Seniority levels from job titles';

-- [core] The 6 salary bands of Analytics Jobs
CREATE TABLE `dim_salary_band` (
  `salary_band_id` TINYINT NOT NULL COMMENT 'Ordinal 1 (lowest) to 6',
  `band_code` VARCHAR(10) NOT NULL COMMENT 'Code as in source, e.g. \'10to15\'',
  `band_label` VARCHAR(20) NOT NULL COMMENT 'Readable label',
  `low_lpa` DECIMAL(5,1) NOT NULL COMMENT 'Lower bound (LPA)',
  `high_lpa` DECIMAL(5,1) NOT NULL COMMENT 'Upper bound (LPA)',
  PRIMARY KEY (`salary_band_id`),
  UNIQUE KEY `uq_band_code` (`band_code`),
  CONSTRAINT `ck_dim_salary_band_1` CHECK (low_lpa < high_lpa)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='The 6 salary bands of Analytics Jobs';

-- [core] Every distinct skill / tag, typed (technical, soft, education, job meta)
CREATE TABLE `dim_skill` (
  `skill_id` SMALLINT NOT NULL COMMENT 'Surrogate key',
  `skill_name` VARCHAR(45) NOT NULL COMMENT 'Normalised skill name',
  `skill_type` ENUM('technical_or_domain','soft','education','job_meta') NOT NULL COMMENT 'Type',
  PRIMARY KEY (`skill_id`),
  UNIQUE KEY `uq_skill_name` (`skill_name`),
  KEY `ix_skill_type` (`skill_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Every distinct skill / tag, typed (technical, soft, education, job meta)';

-- [core] The 5 skill dimensions measured in JDS - the bridge between market and people data
CREATE TABLE `dim_skill_dimension` (
  `dimension_id` TINYINT NOT NULL COMMENT 'Surrogate key',
  `dimension_code` VARCHAR(20) NOT NULL COMMENT 'Code',
  `dimension_name` VARCHAR(40) NOT NULL COMMENT 'Name',
  `jds_score_column` VARCHAR(40) NOT NULL COMMENT 'Matching column in the JDS file',
  PRIMARY KEY (`dimension_id`),
  UNIQUE KEY `uq_dimension_code` (`dimension_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='The 5 skill dimensions measured in JDS - the bridge between market and people data';

-- [core] Which market skills belong to which JDS skill dimension (taxonomy)
CREATE TABLE `map_skill_dimension` (
  `skill_id` SMALLINT NOT NULL COMMENT 'FK dim_skill',
  `dimension_id` TINYINT NOT NULL COMMENT 'FK dim_skill_dimension',
  PRIMARY KEY (`skill_id`, `dimension_id`),
  CONSTRAINT `fk_map_skill_dimension_skill_id` FOREIGN KEY (`skill_id`) REFERENCES `dim_skill` (`skill_id`),
  CONSTRAINT `fk_map_skill_dimension_dimension_id` FOREIGN KEY (`dimension_id`) REFERENCES `dim_skill_dimension` (`dimension_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Which market skills belong to which JDS skill dimension (taxonomy)';

-- [core] Big Five personality traits (SDS)
CREATE TABLE `dim_personality_trait` (
  `trait_id` TINYINT NOT NULL COMMENT 'Surrogate key',
  `trait_code` VARCHAR(30) NOT NULL COMMENT 'Code',
  `trait_name` VARCHAR(30) NOT NULL COMMENT 'Name',
  `description` VARCHAR(200) NOT NULL COMMENT 'Meaning (from the data description)',
  PRIMARY KEY (`trait_id`),
  UNIQUE KEY `uq_trait_code` (`trait_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Big Five personality traits (SDS)';

-- [core] One row per company x job title (DataScience Jobs) - salaries numeric
CREATE TABLE `fact_company_job_title` (
  `company_job_title_id` INT NOT NULL COMMENT 'Key (= stg_row_id)',
  `reference_no` INT NOT NULL COMMENT 'Original id (not unique)',
  `company_id` SMALLINT NOT NULL COMMENT 'FK dim_company',
  `job_title_id` TINYINT NOT NULL COMMENT 'FK dim_job_title',
  `min_experience_years` TINYINT NOT NULL COMMENT 'Minimum experience',
  `min_salary_lpa` DECIMAL(6,2) NOT NULL COMMENT 'Minimum salary (LPA)',
  `avg_salary_lpa` DECIMAL(6,2) NOT NULL COMMENT 'Average salary (LPA)',
  `max_salary_lpa` DECIMAL(6,2) NOT NULL COMMENT 'Maximum salary (LPA)',
  `num_of_jobs` INT NOT NULL COMMENT 'Number of postings',
  `is_min_salary_implausible` TINYINT(1) NOT NULL COMMENT 'min < 1 LPA (monthly/stipend)',
  `is_wide_salary_range` TINYINT(1) NOT NULL COMMENT 'max > 6 x min',
  `is_senior_zero_exp` TINYINT(1) NOT NULL COMMENT 'Senior title, 0 yrs',
  `is_num_jobs_outlier` TINYINT(1) NOT NULL COMMENT 'num_of_jobs > Q3 + 3 IQR',
  `is_salary_outlier_in_title` TINYINT(1) NOT NULL COMMENT 'avg salary > 3 robust SD from title median',
  PRIMARY KEY (`company_job_title_id`),
  UNIQUE KEY `uq_company_title` (`company_id`, `job_title_id`),
  KEY `ix_reference_no` (`reference_no`),
  CONSTRAINT `fk_fact_company_job_title_company_id` FOREIGN KEY (`company_id`) REFERENCES `dim_company` (`company_id`),
  CONSTRAINT `fk_fact_company_job_title_job_title_id` FOREIGN KEY (`job_title_id`) REFERENCES `dim_job_title` (`job_title_id`),
  CONSTRAINT `ck_fact_company_job_title_1` CHECK (min_salary_lpa <= avg_salary_lpa),
  CONSTRAINT `ck_fact_company_job_title_2` CHECK (avg_salary_lpa <= max_salary_lpa),
  CONSTRAINT `ck_fact_company_job_title_3` CHECK (min_experience_years >= 0),
  CONSTRAINT `ck_fact_company_job_title_4` CHECK (num_of_jobs > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='One row per company x job title (DataScience Jobs) - salaries numeric';

-- [core] One row per job posting (Analytics Jobs, exact duplicates removed)
CREATE TABLE `fact_job_posting` (
  `posting_id` INT NOT NULL COMMENT 'Original s_no',
  `job_title_raw` VARCHAR(70) NOT NULL COMMENT 'Designation (whitespace-normalised)',
  `job_title_clean` VARCHAR(70) NOT NULL COMMENT 'Designation without recruiting noise',
  `role_family_id` TINYINT NOT NULL COMMENT 'FK dim_role_family',
  `role_source` ENUM('title','skills','none') NOT NULL COMMENT 'How the family was decided',
  `seniority_id` TINYINT NOT NULL COMMENT 'FK dim_seniority',
  `exp_min_years` TINYINT NOT NULL COMMENT 'Minimum experience',
  `exp_max_years` TINYINT NOT NULL COMMENT 'Maximum experience',
  `salary_band_id` TINYINT NOT NULL COMMENT 'FK dim_salary_band',
  `primary_city_id` SMALLINT NOT NULL COMMENT 'FK dim_city',
  `location_raw` VARCHAR(103) NOT NULL COMMENT 'Location as posted',
  `job_description` TEXT COMMENT 'Description (bullets turned into sentences)',
  `is_job_type_tagged` TINYINT(1) NOT NULL COMMENT 'Raw job_type was filled',
  `is_desc_missing` TINYINT(1) NOT NULL COMMENT 'No description',
  `is_desc_truncated` TINYINT(1) NOT NULL COMMENT 'Description cut off',
  `is_skills_truncated` TINYINT(1) NOT NULL COMMENT 'Skill list cut off',
  `is_near_duplicate` TINYINT(1) NOT NULL COMMENT 'Repeat after normalisation',
  `is_possible_repost` TINYINT(1) NOT NULL COMMENT 'Same as earlier but other salary band',
  `is_spam` TINYINT(1) NOT NULL COMMENT 'Data entry / WFH spam',
  `is_international` TINYINT(1) NOT NULL COMMENT 'Overseas-only location',
  `is_salary_exp_inconsistent` TINYINT(1) NOT NULL COMMENT '0-3 LPA with 8+ years',
  PRIMARY KEY (`posting_id`),
  KEY `ix_posting_role` (`role_family_id`),
  KEY `ix_posting_city` (`primary_city_id`),
  KEY `ix_posting_band` (`salary_band_id`),
  CONSTRAINT `fk_fact_job_posting_role_family_id` FOREIGN KEY (`role_family_id`) REFERENCES `dim_role_family` (`role_family_id`),
  CONSTRAINT `fk_fact_job_posting_seniority_id` FOREIGN KEY (`seniority_id`) REFERENCES `dim_seniority` (`seniority_id`),
  CONSTRAINT `fk_fact_job_posting_salary_band_id` FOREIGN KEY (`salary_band_id`) REFERENCES `dim_salary_band` (`salary_band_id`),
  CONSTRAINT `fk_fact_job_posting_primary_city_id` FOREIGN KEY (`primary_city_id`) REFERENCES `dim_city` (`city_id`),
  CONSTRAINT `ck_fact_job_posting_1` CHECK (exp_max_years >= exp_min_years),
  CONSTRAINT `ck_fact_job_posting_2` CHECK (exp_min_years >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='One row per job posting (Analytics Jobs, exact duplicates removed)';

-- [core] Posting x city (many-to-many: 16% of postings list several cities)
CREATE TABLE `bridge_posting_city` (
  `posting_id` INT NOT NULL COMMENT 'FK fact_job_posting',
  `city_id` SMALLINT NOT NULL COMMENT 'FK dim_city',
  `city_order` TINYINT NOT NULL COMMENT 'Position in the original location list',
  PRIMARY KEY (`posting_id`, `city_id`),
  KEY `ix_pc_city` (`city_id`),
  CONSTRAINT `fk_bridge_posting_city_posting_id` FOREIGN KEY (`posting_id`) REFERENCES `fact_job_posting` (`posting_id`),
  CONSTRAINT `fk_bridge_posting_city_city_id` FOREIGN KEY (`city_id`) REFERENCES `dim_city` (`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Posting x city (many-to-many: 16% of postings list several cities)';

-- [core] Posting x skill (many-to-many), with where the skill was found
CREATE TABLE `bridge_posting_skill` (
  `posting_id` INT NOT NULL COMMENT 'FK fact_job_posting',
  `skill_id` SMALLINT NOT NULL COMMENT 'FK dim_skill',
  `found_in` ENUM('key_skills','description','both') NOT NULL COMMENT 'Source of the mention',
  PRIMARY KEY (`posting_id`, `skill_id`),
  KEY `ix_ps_skill` (`skill_id`),
  CONSTRAINT `fk_bridge_posting_skill_posting_id` FOREIGN KEY (`posting_id`) REFERENCES `fact_job_posting` (`posting_id`),
  CONSTRAINT `fk_bridge_posting_skill_skill_id` FOREIGN KEY (`skill_id`) REFERENCES `dim_skill` (`skill_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Posting x skill (many-to-many), with where the skill was found';

-- [core] Junior data scientists (JDS)
CREATE TABLE `jds_employee` (
  `jds_employee_id` SMALLINT NOT NULL COMMENT 'Surrogate key',
  `source_id` INT NOT NULL COMMENT 'Original id (not unique)',
  `salary_hike_high` TINYINT(1) NOT NULL COMMENT '1 = high performance-based hike',
  PRIMARY KEY (`jds_employee_id`),
  KEY `ix_jds_source` (`source_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Junior data scientists (JDS)';

-- [core] JDS skill scores, one row per employee x skill dimension
CREATE TABLE `fact_jds_skill_score` (
  `jds_employee_id` SMALLINT NOT NULL COMMENT 'FK jds_employee',
  `dimension_id` TINYINT NOT NULL COMMENT 'FK dim_skill_dimension',
  `score` DECIMAL(2,1) NOT NULL COMMENT 'Score 1.0-5.0',
  PRIMARY KEY (`jds_employee_id`, `dimension_id`),
  CONSTRAINT `fk_fact_jds_skill_score_jds_employee_id` FOREIGN KEY (`jds_employee_id`) REFERENCES `jds_employee` (`jds_employee_id`),
  CONSTRAINT `fk_fact_jds_skill_score_dimension_id` FOREIGN KEY (`dimension_id`) REFERENCES `dim_skill_dimension` (`dimension_id`),
  CONSTRAINT `ck_fact_jds_skill_score_1` CHECK (score BETWEEN 1 AND 5)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='JDS skill scores, one row per employee x skill dimension';

-- [core] Senior / client-facing data scientists (SDS)
CREATE TABLE `sds_employee` (
  `sds_employee_id` SMALLINT NOT NULL COMMENT 'Surrogate key',
  `source_id` INT NOT NULL COMMENT 'Original id (not unique)',
  `success_high` TINYINT(1) NOT NULL COMMENT '1 = high success',
  PRIMARY KEY (`sds_employee_id`),
  KEY `ix_sds_source` (`source_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Senior / client-facing data scientists (SDS)';

-- [core] SDS personality scores, one row per employee x trait
CREATE TABLE `fact_sds_trait_score` (
  `sds_employee_id` SMALLINT NOT NULL COMMENT 'FK sds_employee',
  `trait_id` TINYINT NOT NULL COMMENT 'FK dim_personality_trait',
  `score` SMALLINT NOT NULL COMMENT 'Normalised score',
  PRIMARY KEY (`sds_employee_id`, `trait_id`),
  CONSTRAINT `fk_fact_sds_trait_score_sds_employee_id` FOREIGN KEY (`sds_employee_id`) REFERENCES `sds_employee` (`sds_employee_id`),
  CONSTRAINT `fk_fact_sds_trait_score_trait_id` FOREIGN KEY (`trait_id`) REFERENCES `dim_personality_trait` (`trait_id`),
  CONSTRAINT `ck_fact_sds_trait_score_1` CHECK (score BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='SDS personality scores, one row per employee x trait';

-- [metadata] Every data issue found, rows affected and treatment
CREATE TABLE `meta_data_quality_log` (
  `issue_id` SMALLINT NOT NULL COMMENT 'Key',
  `stage` VARCHAR(4) NOT NULL COMMENT 'Pipeline stage S1-S10',
  `source_file` VARCHAR(30) NOT NULL COMMENT 'File',
  `issue_found` VARCHAR(400) NOT NULL COMMENT 'Issue',
  `rows_affected` INT NOT NULL COMMENT 'Rows affected',
  `treatment` VARCHAR(400) NOT NULL COMMENT 'Treatment',
  PRIMARY KEY (`issue_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Every data issue found, rows affected and treatment';

